head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods27010";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods27010.onpageload' });
    }
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_48", entity: "dlt_resourceRoomDetailAttachList", countIds: [], cells: [{ childId: "btn_fileDownload", fn: function (v, i) { return String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldods27010: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fileDownload_onclick
 * @description btn_fileDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileDownload_onclick = function(e){
    try {
        scwin.fileDownload((String(((() => { throw new Error("unresolved:data:" + "result.sprtRoomNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.sprtRoomNo"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "result.sprtRoomNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.sprtRoomNo"); })()))),(String(((() => { throw new Error("unresolved:data:" + "result.attachSeq"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.attachSeq"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "result.attachSeq"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.attachSeq"); })()))),(String(((() => { throw new Error("unresolved:data:" + "result.attachFileNm"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.attachFileNm"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "result.attachFileNm"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "result.attachFileNm"); })()))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods27010.btn_fileDownload_onclick' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록으로」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods27010.btn_list_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods27000/jldods27000.xml");
    $('#ipt_method', $('#searchForm')).val("readResourceRoomList");
    $('#searchForm').submit();
};

/**
 * @method
 * @name fileDownload
 * @description file Download 처리
 * @param {*} sprt_room_no sprt_room_no
 * @param {*} attach_seq attach_seq
 * @param {*} attach_file_nm attach_file_nm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods27010/jldods27010.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
};
